<script setup>
import ChevronText from '../../Components/ChevronText.vue';
import VocabularyText from "../../Components/VocabularyText.vue";
import {languageDirection} from '../../lib/text-direction.js';
import { useDialogEscape } from '../../lib/dialog.js';
import { useI18n } from '../../lib/i18n.js';
import { ref, watch, onBeforeUnmount } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Errors from '../../Components/Errors.vue';
const { t } = useI18n();
const props = defineProps({ words: { type: Object, default: () => ({ data: [], links: [] }) }, selectedPool:{type:Object,default:null}, filters: { type: Object, default: () => ({}) } });
const search = ref(props.filters.search ?? '');
const editing = ref(null); const open = ref(false);
const form = useForm({ pool_id:props.selectedPool?.id??'',term: '', definition: '', note: '' });
function edit(word = null) { if(!props.selectedPool)return;form.pool_id=props.selectedPool.id; editing.value = word?.id ?? null; form.clearErrors(); form.term = word?.term ?? ''; form.definition = word?.definition ?? ''; form.note = word?.note ?? ''; open.value = true; }
function save() { const options = { onSuccess: () => { open.value = false; form.reset(); } }; editing.value ? form.put(`/words/${editing.value}`, options) : form.post('/words', options); }
const poolOpen=ref(false),poolForm=useForm({name:'',language:'',text_direction:'ltr'});
function editPool(){directionChosen.value=true;poolForm.text_direction=props.selectedPool.text_direction??'ltr';poolForm.clearErrors();poolForm.name=props.selectedPool.name;poolForm.language=props.selectedPool.language;poolOpen.value=true;}
const directionChosen=ref(false);
watch(()=>poolForm.language,language=>{poolForm.text_direction=languageDirection(language,poolForm.text_direction,directionChosen.value);},{flush:'sync'});
function savePool(){const options={onSuccess:()=>{poolOpen.value=false;}};poolForm.put(`/word-pools/${props.selectedPool.id}`,options);}
function deletePool(){if(confirm(t('Delete this pool? Words, notes and collection links are kept. Words without another pool will not appear until added to a pool.')))poolForm.delete(`/word-pools/${props.selectedPool.id}`);}
function searchWords(){router.get(`/word-pools/${props.selectedPool.id}`,{search:search.value.trim()},{preserveState:true,replace:true});}
watch(()=>props.filters.search,value=>{search.value=value??'';});
function remove(word){if(confirm(t('Remove “{term}” from this pool only? Its other pools, notes and collection links are kept.',{term:word.term})))router.delete(`/word-pools/${props.selectedPool.id}/words/${word.id}`,{preserveScroll:true});}
const reuseOpen=ref(false),reuseQuery=ref(''),reusePage=ref({data:[]}),reuseLoading=ref(false),reuseError=ref(false),reuse=useForm({word_ids:[]});
let reuseController;
async function loadReuse(url=null){
 if(!props.selectedPool)return;
 reuseController?.abort();const controller=new AbortController();reuseController=controller;reuseLoading.value=true;reuseError.value=false;
 try{const response=await fetch(url??`/word-pools/${props.selectedPool.id}/available-words?search=${encodeURIComponent(reuseQuery.value.trim())}`,{headers:{Accept:'application/json'},credentials:'same-origin',signal:controller.signal});if(!response.ok)throw Error();const data=await response.json();if(reuseController===controller)reusePage.value=data;}
 catch(e){if(e.name!=='AbortError')reuseError.value=true;}finally{if(reuseController===controller)reuseLoading.value=false;}
}
function openReuse(){reuse.reset();reuseQuery.value='';reusePage.value={data:[]};reuseOpen.value=true;loadReuse();}
function closeReuse(){reuseOpen.value=false;reuseController?.abort();}
function saveReuse(){reuse.post(`/word-pools/${props.selectedPool.id}/words`,{preserveScroll:true,onSuccess:closeReuse});}
onBeforeUnmount(()=>reuseController?.abort());
function pageLabel(label) { if (/previous/i.test(label)) return t('← Previous'); if (/next/i.test(label)) return t('Next →'); return label; }
useDialogEscape(() => { open.value = false;poolOpen.value=false;closeReuse(); });
</script>
<template>
    <Head :title="t('Word pool')" />
    <AppLayout :title="selectedPool?.name??t('Word pools')" :subtitle="t('Every word is a small discovery.')">
        <template #actions><div class="actions"><Link href="/words" class="button secondary"><ChevronText :text="t('← Word pools')"/></Link><template v-if="selectedPool"><a :href="`/words/export?pool_id=${selectedPool.id}`" class="button secondary">{{t('Export CSV')}}</a><Link :href="`/imports?pool_id=${selectedPool.id}`" class="button secondary">{{t('Import CSV')}}</Link><button class="button" @click="edit()">{{t('+ Add a word')}}</button></template></div></template>
        <section class="panel pool-toolbar"><span class="pill">{{selectedPool.language}}</span><div v-if="selectedPool" class="actions"><button class="button secondary" @click="editPool(selectedPool)">{{t('Edit pool')}}</button><button class="button secondary" @click="openReuse">{{t('Reuse existing words')}}</button><button class="text-button danger" @click="deletePool">{{t('Delete pool')}}</button></div></section>
        <form v-if="selectedPool" class="search-row" @submit.prevent="searchWords"><input v-model="search" type="search" :placeholder="t('Search words and definitions…')" :aria-label="t('Search words')" /><button class="button secondary">{{ t('Search') }}</button><span class="muted">{{ t('{count} words', { count: words.total ?? words.data.length }) }}</span></form>
        <div class="word-list"><article class="word-row editable" v-for="word in words.data" :key="word.id"><div><VocabularyText as="strong" :text="word.term" :direction="word.text_direction"/><VocabularyText as="p" :text="word.definition" :direction="word.text_direction"/><div v-if="word.note" class="personal-note"><span>{{ t('YOUR NOTE') }}</span>{{ word.note }}</div></div><div class="actions"><button class="text-button" @click="edit(word)">{{ t('Edit') }}</button><button class="text-button danger" @click="remove(word)">{{ t('Remove from pool') }}</button></div></article><div v-if="selectedPool&&!words.data.length" class="empty"><span>≋</span><h3>{{ t(search ? 'No matching words.' : 'A blank page, full of possibility.') }}</h3><p>{{ t(search ? 'Try another search.' : 'Add a word or bring your vocabulary in with a CSV.') }}</p><button v-if="!search" class="button" @click="edit()">{{ t('Add your first word') }}</button></div></div>
        <nav class="pagination" :aria-label="t('Pagination')"><template v-for="(link, index) in words.links" :key="index"><Link v-if="link.url" :href="link.url" :class="{ active: link.active }" :aria-current="link.active ? 'page' : undefined"><ChevronText :text="pageLabel(link.label)"/></Link><span v-else><ChevronText :text="pageLabel(link.label)"/></span></template></nav>
        <div v-if="open" class="modal-backdrop" @click.self="open = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="word-title"><div class="section-heading"><h2 id="word-title">{{ t(editing ? 'Edit word' : 'A new discovery') }}</h2><button class="icon-button" :aria-label="t('Close')" @click="open = false">×</button></div><form @submit.prevent="save"><Errors :errors="form.errors" /><label>{{ t('Word or phrase') }}<input dir="auto" v-model="form.term" required maxlength="500" autofocus /></label><label>{{ t('Original definition') }}<textarea dir="auto" v-model="form.definition" maxlength="5000" required rows="3" /></label><label>{{ t('Your private note') }}<textarea dir="auto" v-model="form.note" maxlength="5000" rows="2" :placeholder="t('A translation, a memory, a little context…')" /></label><p v-if="editing" class="notice">{{t('Editing this word updates every pool and collection that uses it. To keep a different meaning, create a separate word.')}}</p><p class="muted small">{{ t('Personal notes never appear on shared collection links.') }}</p><div class="form-actions"><button type="button" class="button secondary" @click="open = false">{{ t('Cancel') }}</button><button class="button" :disabled="form.processing">{{ t('Save word') }}</button></div></form></section></div>
        <div v-if="poolOpen" class="modal-backdrop" @click.self="poolOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="pool-title"><h2 id="pool-title">{{t('Edit pool')}}</h2><form @submit.prevent="savePool"><Errors :errors="poolForm.errors"/><label>{{t('Pool name')}}<input v-model="poolForm.name" required maxlength="150"/></label><label>{{t('Language code')}}<input v-model="poolForm.language" list="pool-languages" required maxlength="35" placeholder="en-US, pt-PT, tr"/></label><label>{{t('Text direction')}}<select v-model="poolForm.text_direction" @change="directionChosen=true"><option value="ltr">{{t('Left to right (LTR)')}}</option><option value="rtl">{{t('Right to left (RTL)')}}</option></select></label><datalist id="pool-languages"><option value="ar">العربية</option><option value="he">עברית</option><option value="fa">فارسی</option><option value="ur">اردو</option><option value="en-US">English (US)</option><option value="en-GB">English (UK)</option><option value="pt-PT">Português</option><option value="tr">Türkçe</option><option value="de">Deutsch</option><option value="es">Español</option><option value="fr">Français</option></datalist><p class="muted small">{{t('Use a language code such as en-US or pt-PT. Words keep their original spelling and definition.')}}</p><div class="form-actions"><button type="button" class="button secondary" @click="poolOpen=false">{{t('Cancel')}}</button><button class="button" :disabled="poolForm.processing">{{t('Save pool')}}</button></div></form></section></div>
        <div v-if="reuseOpen" class="modal-backdrop" @click.self="closeReuse"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reuse-title"><h2 id="reuse-title">{{t('Reuse existing words')}}</h2><p>{{t('Reuse keeps the same word, definition and private note across pools. Different meanings should be separate words.')}}</p><form @submit.prevent="loadReuse()"><label>{{t('Search words')}}<input v-model="reuseQuery" type="search"/></label><button class="button secondary" :disabled="reuseLoading">{{t('Search')}}</button></form><p v-if="reuseLoading" role="status">{{t('Loading…')}}</p><p v-if="reuseError" class="notice error" role="alert">{{t('Could not load words. Try searching again.')}}</p><form @submit.prevent="saveReuse"><Errors :errors="reuse.errors"/><label v-for="word in reusePage.data" :key="word.id" class="reuse-word"><input type="checkbox" v-model="reuse.word_ids" :value="word.id" :disabled="reuse.processing||(!reuse.word_ids.includes(word.id)&&reuse.word_ids.length>=500)"/><span><VocabularyText as="strong" :text="word.term" :direction="word.text_direction"/><VocabularyText as="small" :text="word.definition" :direction="word.text_direction"/></span></label><div class="actions"><button v-if="reusePage.prev_page_url" type="button" class="button secondary" :disabled="reuseLoading" @click="loadReuse(reusePage.prev_page_url)"><ChevronText :text="t('← Previous')"/></button><button v-if="reusePage.next_page_url" type="button" class="button secondary" :disabled="reuseLoading" @click="loadReuse(reusePage.next_page_url)"><ChevronText :text="t('Next →')"/></button></div><div class="form-actions"><button type="button" class="button secondary" @click="closeReuse">{{t('Cancel')}}</button><button class="button" :disabled="reuse.processing||!reuse.word_ids.length">{{t('Add {count} words',{count:reuse.word_ids.length})}}</button></div></form></section></div>
    </AppLayout>
</template>

<style scoped>.pool-toolbar{margin-bottom:20px;display:flex;flex-direction:column;align-items:flex-start;gap:20px}.pool-toolbar .actions{width:100%;gap:12px}.pool-toolbar .pill{margin:0}.pool-toolbar .actions .button,.pool-toolbar .actions .text-button{min-height:44px}.pool-toolbar label{margin-bottom:14px}.reuse-word{display:flex;flex-direction:row;align-items:flex-start;gap:12px;padding:10px 0}.reuse-word input{width:18px;flex:0 0 18px;accent-color:var(--teal)}.reuse-word small{display:block;white-space:pre-wrap}.reuse-word span{min-width:0;overflow-wrap:anywhere}@media(max-width:600px){.pool-toolbar .actions,.form-actions{flex-direction:column;align-items:stretch}}</style>
